const i = $('When Called').first().json;
const b = $input.first().json;
const sizes = { square: '1024x1024', portrait: '1024x1536', landscape: '1536x1024', story: '1024x1536' };
const size = sizes[String(i.size || 'square').toLowerCase()] || (/^\d+x\d+$/.test(String(i.size)) ? String(i.size) : '1024x1024');
const rules = ' Professional travel-agency advertising design for Al Mutawa Tourism (المطوع للسياحة), Bahrain. Clean, premium, navy and gold. Write all Arabic text exactly as given, right-to-left, correct spelling. STRICT: do NOT invent prices, dates, phone numbers, websites or offers; only show details written in this request. Never draw any other or made-up logo.';
const mode = String(i.mode || 'new').toLowerCase();
const isEdit = mode === 'edit' && !!b.b64;
const prompt = isEdit ? ('Edit this advertisement image. Apply ONLY these changes and keep everything else (layout, text, colors, photos, logo) the same: ' + String(i.prompt || '') + rules) : ('Create a brand-new advertisement design. The attached image is the OFFICIAL office logo: place it exactly as it is (same shape, colors and text, not redrawn, not distorted) clearly in a top corner of the design. Design brief: ' + String(i.prompt || '') + rules);
const out = { json: { isEdit, mode: isEdit ? 'edit' : (mode === 'redesign' ? 'redesign' : 'new'), prompt, size: isEdit ? 'auto' : size, package_id: String(i.package_id || b.base_package_id || ''), name: String(i.name || 'design'), base_design_id: String(i.base_design_id || ''), brief: String(i.brief || b.base_brief || ''), feedback: isEdit ? String(i.prompt || '') : '' } };
if (isEdit) out.binary = { data: { data: b.b64, mimeType: 'image/png', fileName: 'base.png' } };
return [out];

const r = $input.first().json;
const b = r.body || {};
const d = (b.data || [])[0] || {};
if (!d.b64_json) return [{ json: { b64: '', error: (b.error && b.error.message) || ('HTTP ' + r.statusCode) } }];
return [{ json: { b64: d.b64_json, error: '' } }];

const r = $input.first().json;
if (!r.url) return [{ json: { ok: false, error: r.error || 'image generation failed' } }];
return [{ json: { ok: true, design_id: r.design_id, image_url: r.url, package_id: r.package_id, show_to_user: '![\u062a\u0635\u0645\u064a\u0645 ' + r.design_id + '](' + r.url + ')\n\n[[\u2705 \u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0644\u062a\u0635\u0645\u064a\u0645 ' + r.design_id + ']] [[\u270f\ufe0f \u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 ' + r.design_id + ']] [[\ud83d\udd04 \u062a\u0635\u0645\u064a\u0645 \u062c\u062f\u064a\u062f \u0628\u062f\u0644 ' + r.design_id + ']]', note: 'Paste show_to_user exactly at the end of your reply. Not approved yet; the package photo changes only after approval.' } }];

